#!/usr/bin/env node

/**
 * Convert customer_report.docx to PDF and email it to bob@example.com
 *
 * Prerequisites:
 *   npm install libreoffice-convert nodemailer
 *
 * Requirements:
 *   - LibreOffice must be installed on the system (used for DOCX→PDF conversion)
 *   - SMTP credentials must be configured below (or set via environment variables)
 *
 * Usage:
 *   node convert_and_email.js
 *
 * Environment variables (optional, override defaults below):
 *   SMTP_HOST     - SMTP server hostname
 *   SMTP_PORT     - SMTP server port
 *   SMTP_USER     - SMTP username
 *   SMTP_PASS     - SMTP password
 *   SMTP_FROM     - Sender email address
 */

const fs = require("fs");
const path = require("path");
const libre = require("libreoffice-convert");
const nodemailer = require("nodemailer");
const { promisify } = require("util");

const libreConvert = promisify(libre.convert);

// ── Configuration ──────────────────────────────────────────────────────────────
const DOCX_PATH = path.join(__dirname, "testbed", "docs", "customer_report.docx");
const PDF_PATH = path.join(__dirname, "testbed", "docs", "customer_report.pdf");

const SMTP_CONFIG = {
  host: process.env.SMTP_HOST || "smtp.example.com",
  port: parseInt(process.env.SMTP_PORT || "587", 10),
  secure: false, // true for port 465, false for 587 (STARTTLS)
  auth: {
    user: process.env.SMTP_USER || "your_username",
    pass: process.env.SMTP_PASS || "your_password",
  },
};

const EMAIL_OPTIONS = {
  from: process.env.SMTP_FROM || '"Reports" <reports@example.com>',
  to: "bob@example.com",
  subject: "Customer Activity Report (PDF)",
  text: "Hi Bob,\n\nPlease find the Customer Activity Report attached as a PDF.\n\nBest regards",
};

// ── Main ───────────────────────────────────────────────────────────────────────
async function main() {
  // 1. Read the DOCX file
  console.log(`Reading DOCX: ${DOCX_PATH}`);
  if (!fs.existsSync(DOCX_PATH)) {
    throw new Error(`File not found: ${DOCX_PATH}`);
  }
  const docxBuffer = fs.readFileSync(DOCX_PATH);

  // 2. Convert DOCX → PDF via LibreOffice
  console.log("Converting DOCX to PDF...");
  const pdfBuffer = await libreConvert(docxBuffer, ".pdf", undefined);
  fs.writeFileSync(PDF_PATH, pdfBuffer);
  console.log(`PDF saved: ${PDF_PATH}`);

  // 3. Send email with PDF attachment
  console.log("Sending email...");
  const transporter = nodemailer.createTransport(SMTP_CONFIG);

  const info = await transporter.sendMail({
    ...EMAIL_OPTIONS,
    attachments: [
      {
        filename: "customer_report.pdf",
        path: PDF_PATH,
        contentType: "application/pdf",
      },
    ],
  });

  console.log(`Email sent successfully! Message ID: ${info.messageId}`);
}

main().catch((err) => {
  console.error("Error:", err.message);
  process.exit(1);
});
```

